-- =====================================================================
-- FYNDO: 71 REAL places in Colombo 3/4/5/7, Dehiwala and Mount Lavinia.
-- Names, positions, phones and hours come from OpenStreetMap (ODbL, (c) OpenStreetMap contributors).
-- Prices, menus and videos are NOT included: add them in Admin after you visit. None are marked Verified.
-- How to use: Supabase > SQL Editor > New query > paste this whole file > Run. Safe to run again.
-- Remove the made-up sample places afterwards:  delete from public.spots where name like '%(Sample)%';
-- =====================================================================
alter table public.spots add column if not exists features text[] default '{}';

on conflict (id) do nothing;
